const input = $json.body ?? $json;

const text = (value) => {
  if (value === null || value === undefined) return '';
  return String(value).trim();
};

const toBoolean = (value) => {
  if (typeof value === 'boolean') return value;
  return ['true', '1', 'yes', 'on'].includes(text(value).toLowerCase());
};

const clinic_name = text(input.clinic_name);
const doctor_name = text(input.doctor_name);
const service_name = text(input.service_name);
const target_date = text(input.target_date);
const start_time = text(input.start_time);
const offer_expiry_minutes = Number(input.offer_expiry_minutes ?? 30);
const source = text(input.source || 'assistant');
const confirm_offer = toBoolean(input.confirm_offer);

const errors = [];

function isRealIsoDate(value) {
  if (!/^\d{4}-\d{2}-\d{2}$/.test(value)) return false;

  const [year, month, day] = value.split('-').map(Number);
  const parsed = new Date(Date.UTC(year, month - 1, day));

  return (
    parsed.getUTCFullYear() === year &&
    parsed.getUTCMonth() === month - 1 &&
    parsed.getUTCDate() === day
  );
}

if (!clinic_name) {
  errors.push({
    field: 'clinic_name',
    message: 'نام کلینیک الزامی است.',
  });
}

if (!doctor_name) {
  errors.push({
    field: 'doctor_name',
    message: 'نام پزشک الزامی است.',
  });
}

if (!service_name) {
  errors.push({
    field: 'service_name',
    message: 'نام خدمت الزامی است.',
  });
}

if (!isRealIsoDate(target_date)) {
  errors.push({
    field: 'target_date',
    message: 'تاریخ باید معتبر و با قالب YYYY-MM-DD باشد.',
  });
}

if (!/^([01]\d|2[0-3]):[0-5]\d$/.test(start_time)) {
  errors.push({
    field: 'start_time',
    message: 'ساعت باید با قالب HH:MM باشد.',
  });
}

if (
  !Number.isInteger(offer_expiry_minutes) ||
  offer_expiry_minutes < 5 ||
  offer_expiry_minutes > 1440
) {
  errors.push({
    field: 'offer_expiry_minutes',
    message: 'زمان اعتبار پیشنهاد باید یک عدد صحیح بین 5 و 1440 دقیقه باشد.',
  });
}

if (!['assistant', 'secretary', 'admin', 'system'].includes(source)) {
  errors.push({
    field: 'source',
    message: 'source باید assistant، secretary، admin یا system باشد.',
  });
}

if (confirm_offer !== true) {
  errors.push({
    field: 'confirm_offer',
    message: 'ارسال پیشنهاد باید به‌صورت صریح تأیید شود.',
  });
}

return [
  {
    json: {
      clinic_name,
      doctor_name,
      service_name,
      target_date,
      start_time,
      offer_expiry_minutes,
      source,
      confirm_offer,
      validation_status: errors.length === 0 ? 'valid' : 'invalid',
      errors,
    },
  },
];

return [
  {
    json: {
      success: false,
      result: 'invalid_request',
      message: 'اطلاعات درخواست پیشنهاد زمان ناقص یا نامعتبر است.',
      next_action: 'none',
      errors: $json.errors ?? [],
    },
  },
];
